import re as _re
def GEX(k,g):
    def f(m):
        if k in MEX: return "<p><span class='us'>"+m.group(1)+"</span><span class='mt'>"+MEX[k]+"</span></p>"
        if k in _NOM: return "<p class='nocv'>"+m.group(1)+"</p>"
        return m.group(0)
    return _re.sub(r'<p>(<b>Example:</b>.*?)</p>',f,g,flags=_re.S)
