# Host canonicalisation: *.pages.dev and www -> apex (301, path + query preserved)
TOOLSET=[d for d in os.listdir("dist") if os.path.exists(f"dist/{d}/index.html") and d not in ("about","privacy","contact")]
open("dist/_worker.js","w").write(open("ev_worker.js").read()+"\nconst TOOLS=new Set("+json.dumps(sorted(TOOLSET))+");"+"""\nexport default{async fetch(req,env){const u=new URL(req.url),h=u.hostname,apex=new URL(SITE).hostname;if(h!==apex&&h!=='localhost'&&(h.endsWith('.pages.dev')||h==='www.'+apex)){return Response.redirect(SITE+u.pathname+u.search,301)}if(u.pathname==='/api/e')return ev(req,env,'porchmath','porchmath.com',TOOLS);if(u.pathname==='/api/usage')return usage(req,env,'porchmath');return env.ASSETS.fetch(req)}};""".replace("SITE+","'"+SITE+"'+").replace("new URL(SITE)","new URL('"+SITE+"')"))
import subprocess
import glob as _g,shutil as _sh
_sh.copy("t.js","dist/t.js")
for _f in _g.glob("dist/**/*.html",recursive=True):
    _h=open(_f).read()
    if "/t.js" not in _h:open(_f,"w").write(_h.replace("</body>","<script src='/t.js' defer></script></body>",1))
